// AFTER: Separated into focused services with explicit interfaces
public interface IOrderService
{
    Task<OrderResult> CreateAsync(CreateOrderRequest request, CancellationToken ct);
}

public class OrderService : IOrderService
{
    private readonly IOrderRepository _orders;
    private readonly IPaymentProcessor _payments;
    private readonly INotificationService _notifications;
    private readonly IInventoryService _inventory;
    private readonly IAuditLogger _audit;

    public async Task<OrderResult> CreateAsync(CreateOrderRequest request, CancellationToken ct)
    {
        var order = Order.Create(request);
        await _orders.AddAsync(order, ct);
        await _payments.ChargeAsync(order.Total, ct);
        await _notifications.SendConfirmationAsync(order.CustomerId, order.Id, ct);
        await _inventory.ReserveAsync(order.Id, order.Items, ct);
        await _audit.LogAsync("OrderCreated", order.Id, ct);
        return OrderResult.From(order);
    }
}

