public decimal CalculateTotal(Order o)
{
    decimal t = 0;
    foreach (var i in o.Items)
    {
        t = t + i.Price * i.Qty;
    }
    if (o.HasDiscount)
    {
        t = t * 0.9m;
    }
    return t;
}

// You leave it cleaner:
public decimal CalculateTotal(Order order)
{
    ArgumentNullException.ThrowIfNull(order);
    var subtotal = order.Items.Sum(item => item.Price * item.Quantity);
    return order.HasDiscount ? subtotal * 0.9m : subtotal;
}
